"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([["9061"],{2161(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>h,frontMatter:()=>o,contentTitle:()=>s,toc:()=>d,assets:()=>l});var a=JSON.parse('{"id":"standards/automation-practices","title":"Automation & Tooling Practices","description":"Reusable engineering technique, generalized out of real automation work.","source":"@site/content/internal/standards/automation-practices.md","sourceDirName":"standards","slug":"/standards/automation-practices","permalink":"/docs/internal/standards/automation-practices","draft":false,"unlisted":false,"editUrl":"https://github.com/PanderoseCore/panderose-deploy/tree/main/docs-src/content/internal/standards/automation-practices.md","tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3,"title":"Automation & Tooling Practices"},"sidebar":"internalSidebar","previous":{"title":"Public vs. Internal \u2014 Classification Policy","permalink":"/docs/internal/standards/classification"},"next":{"title":"Internal Systems","permalink":"/docs/internal/systems/"}}'),i=t(4848),r=t(8453);let o={sidebar_position:3,title:"Automation & Tooling Practices"},s="Automation & Tooling Practices",l={},d=[{value:"1. Dry-run-by-default for anything that sends real communication",id:"1-dry-run-by-default-for-anything-that-sends-real-communication",level:2},{value:"2. Local template rendering as a fallback when a vendor SDK doesn&#39;t support what its dashboard promises",id:"2-local-template-rendering-as-a-fallback-when-a-vendor-sdk-doesnt-support-what-its-dashboard-promises",level:2},{value:"3. Splitting &quot;client-safe&quot; detail from &quot;operator-only&quot; detail on every check/finding result",id:"3-splitting-client-safe-detail-from-operator-only-detail-on-every-checkfinding-result",level:2},{value:"4. A suppression list for known, accepted findings, kept separate from full internal detail",id:"4-a-suppression-list-for-known-accepted-findings-kept-separate-from-full-internal-detail",level:2},{value:"5. Approve/deny-by-reply instead of building a bespoke approval UI",id:"5-approvedeny-by-reply-instead-of-building-a-bespoke-approval-ui",level:2},{value:"6. Single-use, expiring approve/deny tokens for a webhook-driven gate",id:"6-single-use-expiring-approvedeny-tokens-for-a-webhook-driven-gate",level:2},{value:"7. Decoupling a scheduled job from any interactive session that might not be running",id:"7-decoupling-a-scheduled-job-from-any-interactive-session-that-might-not-be-running",level:2},{value:"8. Fail-loud on the failure path, using a different runtime than the main pipeline",id:"8-fail-loud-on-the-failure-path-using-a-different-runtime-than-the-main-pipeline",level:2},{value:"9. Scoping a service credential to the one resource it needs, even when a broader grant would be simpler",id:"9-scoping-a-service-credential-to-the-one-resource-it-needs-even-when-a-broader-grant-would-be-simpler",level:2},{value:"10. Encrypting an unattended job&#39;s credentials at rest, decrypted only into memory for the run&#39;s duration",id:"10-encrypting-an-unattended-jobs-credentials-at-rest-decrypted-only-into-memory-for-the-runs-duration",level:2},{value:"11. Verify a live capability by actually exercising it once, not by reading the docs",id:"11-verify-a-live-capability-by-actually-exercising-it-once-not-by-reading-the-docs",level:2},{value:"Left out",id:"left-out",level:2}];function c(e){let n={a:"a",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",ul:"ul",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"automation--tooling-practices",children:"Automation & Tooling Practices"})}),"\n",(0,i.jsx)(n.p,{children:'Reusable engineering technique, generalized out of real automation work.\nDeliberately excludes client identity, incident specifics, vendor names,\ndates, dollar amounts, credentials, and infrastructure identifiers \u2014 none\nof that appears below, and none of it should be inferred from what does.\nWhere a technique couldn\'t be described without the description itself\npointing back at who or what it was built for, it was left out rather\nthan generalized (see "Left out" at the end).'}),"\n",(0,i.jsx)(n.h2,{id:"1-dry-run-by-default-for-anything-that-sends-real-communication",children:"1. Dry-run-by-default for anything that sends real communication"}),"\n",(0,i.jsxs)(n.p,{children:["A script that sends an email, a message, or any other outward-facing\ncommunication defaults to a dry run \u2014 printing the payload it would send\ninstead of sending it \u2014 whenever a required credential/API key isn't set in\nthe environment, ",(0,i.jsx)(n.em,{children:"and"})," also whenever a ",(0,i.jsx)(n.code,{children:"--dry-run"}),' flag is passed\nexplicitly. This gives two independent safety rails instead of one: an\nengineer working on the script locally without the real credential can\'t\naccidentally send something live, and even with the credential present,\nan explicit flag lets a real run be rehearsed. The pattern is cheap to add\n(a boolean check ahead of the actual send call) and removes an entire class\nof "oops, that email went out for real" mistakes during development.']}),"\n",(0,i.jsx)(n.h2,{id:"2-local-template-rendering-as-a-fallback-when-a-vendor-sdk-doesnt-support-what-its-dashboard-promises",children:"2. Local template rendering as a fallback when a vendor SDK doesn't support what its dashboard promises"}),"\n",(0,i.jsxs)(n.p,{children:["A transactional-email provider's dashboard supported managed templates with\nvariable substitution, but the ",(0,i.jsx)(n.em,{children:"client library actually installed"})," had no\ncode path to use a template by ID with variables \u2014 calling it that way\nfailed outright. Rather than fight the SDK or pin to an undocumented\ninternal API, the fix was to keep a plain copy of the template's HTML/text\nlocally and do simple ",(0,i.jsx)(n.code,{children:"{{TOKEN}}"})," substitution before calling the SDK's\nplain \"send html/text\" method \u2014 the one call path that was actually\nsupported. The general lesson: when a vendor's dashboard feature and its\nofficial client library disagree, verify which one the SDK you actually\ncall supports (by reading its source or by a real test call, not just its\ndocs), and fall back to the simplest working primitive rather than building\naround an unsupported path."]}),"\n",(0,i.jsx)(n.h2,{id:"3-splitting-client-safe-detail-from-operator-only-detail-on-every-checkfinding-result",children:'3. Splitting "client-safe" detail from "operator-only" detail on every check/finding result'}),"\n",(0,i.jsx)(n.p,{children:"A monitoring or scanning script's individual result objects carried two\nseparate detail fields from the start: one meant to ever reach an external\naudience (plain-language, no internal identifiers), and one meant only for\nthe person operating the tool (raw error text, trace/correlation IDs,\nanything from a lower-level API response). Whatever renders an\nexternal-facing summary reads only the first field; an internal-facing\ndetailed view can show both. This avoids a whole class of leak where a raw\nexception string \u2014 which can contain internal identifiers never meant to\nbe seen outside the team \u2014 ends up copy-pasted into something that goes to\nan external audience, because the rendering code was never given a\nseparate, deliberately-narrower field to read from in the first place."}),"\n",(0,i.jsx)(n.h2,{id:"4-a-suppression-list-for-known-accepted-findings-kept-separate-from-full-internal-detail",children:"4. A suppression list for known, accepted findings, kept separate from full internal detail"}),"\n",(0,i.jsx)(n.p,{children:"Recurring automated checks will often flag the same known, already-accepted\nlimitation every single run (a missing license tier, a setting that can't\nbe changed yet, etc.). Rather than either hiding it entirely or re-alarming\non it every cycle, the pattern used here is a small, explicit \"don't surface\nthis externally\" list of check names, applied only at the point of building\nan external-facing summary \u2014 the full internal report still shows every\nfinding, every run, in full detail. This keeps an external summary from\nbecoming noisy with things the recipient already knows about and can't act\non, without ever hiding information from the people who actually need to\nsee everything."}),"\n",(0,i.jsx)(n.h2,{id:"5-approvedeny-by-reply-instead-of-building-a-bespoke-approval-ui",children:"5. Approve/deny-by-reply instead of building a bespoke approval UI"}),"\n",(0,i.jsx)(n.p,{children:'Where a recurring automated job produces something that must not go out\nwithout a person\'s sign-off, one workable shape needs no new service to\nbuild or secure: the job pushes a short one-line summary as a\nphone/desktop push notification, and a person\'s plain-text reply of\n"approve" or "deny" (in whatever ongoing channel already exists \u2014 a chat\nsession, a messaging thread) is the gate. Nothing sends until that reply\narrives, and the mechanism is deliberately just "reply to a message," not a\ndashboard, login, or ticketing system. The tradeoff is explicit: this\nworks well for a single approver on a small number of recurring decisions,\nand stops being appropriate the moment more than one person needs to\napprove, or an audit trail beyond message history is required.'}),"\n",(0,i.jsx)(n.h2,{id:"6-single-use-expiring-approvedeny-tokens-for-a-webhook-driven-gate",children:"6. Single-use, expiring approve/deny tokens for a webhook-driven gate"}),"\n",(0,i.jsx)(n.p,{children:"Where the approval step above is instead implemented as a real\nclickable-link webhook (rather than a plain-text reply), each run generates\nits own single-use token pair (one value for approve, one for deny) tied to\nthat specific run's identity. The webhook checks the token against a\npending-approval record before doing anything, and consumes it once used \u2014\nso a stale link from an old run, or a resent/replayed link, can't retrigger\nan already-decided action. A daily reminder job re-sends the same\nnotification if a run sits unanswered, capped at a small fixed number of\nreminders so it goes quiet rather than nagging forever."}),"\n",(0,i.jsx)(n.h2,{id:"7-decoupling-a-scheduled-job-from-any-interactive-session-that-might-not-be-running",children:"7. Decoupling a scheduled job from any interactive session that might not be running"}),"\n",(0,i.jsxs)(n.p,{children:["A recurring job that must run unattended (whether or not any particular\nlaptop, chat session, or interactive tool is open at the time) belongs on\nthe host's own OS-level scheduler (a timer/cron-equivalent running as a\nsystem service), not inside any session-scoped mechanism whose lifetime is\ntied to that session. A job scheduled ",(0,i.jsx)(n.em,{children:"inside"})," an interactive assistant\nsession, for instance, only persists as long as that mechanism's own\nsession state does and can silently stop firing once that expires \u2014 which\nis a fragile foundation for anything that has to keep happening\nindefinitely. The general principle: schedule ongoing automation as close\nto the operating system as possible, and treat any tool-session-based\nscheduling as a prototyping convenience at best, never the durable\nmechanism."]}),"\n",(0,i.jsx)(n.h2,{id:"8-fail-loud-on-the-failure-path-using-a-different-runtime-than-the-main-pipeline",children:"8. Fail-loud on the failure path, using a different runtime than the main pipeline"}),"\n",(0,i.jsx)(n.p,{children:'A scheduled pipeline\'s top-level error handler sends an urgent\nfailure notification using the simplest, most independent mechanism\navailable (e.g. a raw HTTP call from the shell/orchestration layer) rather\nthan routing the failure notice through the same runtime whose failure is\nbeing reported. The reasoning: if the failure is in the main runtime\nitself, a notification path that also depends on that runtime might never\nfire. Keeping the "something broke" alert on a simpler, separate code path\nmakes it more likely the alert itself survives whatever broke.'}),"\n",(0,i.jsx)(n.h2,{id:"9-scoping-a-service-credential-to-the-one-resource-it-needs-even-when-a-broader-grant-would-be-simpler",children:"9. Scoping a service credential to the one resource it needs, even when a broader grant would be simpler"}),"\n",(0,i.jsxs)(n.p,{children:["When an automated job needs write access to one specific shared folder/\nresource (not a whole account or tenant), prefer an application permission\nmodel that grants ",(0,i.jsx)(n.em,{children:"zero"}),' access by default and then explicitly grant it\naccess to only that one resource, over a broader "read/write everything"\npermission that would technically also work and require less one-time\nsetup. It costs one extra one-time step (a scoped grant call) in exchange\nfor a service identity that can\'t reach anything beyond what it was built\nto touch \u2014 worth it for anything that runs unattended and holds a\nlong-lived credential.']}),"\n",(0,i.jsx)(n.h2,{id:"10-encrypting-an-unattended-jobs-credentials-at-rest-decrypted-only-into-memory-for-the-runs-duration",children:"10. Encrypting an unattended job's credentials at rest, decrypted only into memory for the run's duration"}),"\n",(0,i.jsx)(n.p,{children:"Where an unattended scheduled job needs a persistent credential (a\ncertificate, an API key) on a machine it runs on, encrypt it at rest with a\nhost- or hardware-bound mechanism, decrypting into a private, non-persistent\nlocation only for the duration of each run \u2014 never left as plaintext on\ndisk. When the underlying hardware supports it, binding the encryption to a\nhardware root of trust (rather than just the host OS) is a meaningful step\nup: it means even a full disk copy isn't enough to recover the secret\nwithout that same physical device. This is worth the modest one-time setup\ncost for anything unattended and long-lived; it isn't worth it for a\ncredential used interactively and rotated often."}),"\n",(0,i.jsx)(n.h2,{id:"11-verify-a-live-capability-by-actually-exercising-it-once-not-by-reading-the-docs",children:"11. Verify a live capability by actually exercising it once, not by reading the docs"}),"\n",(0,i.jsx)(n.p,{children:"More than one real bug in a communications pipeline (a client SDK silently\nnot supporting a documented feature, a template placeholder nothing ever\npopulated, a \"from\" address that looked valid but wasn't on a verified\nsending domain) was only caught by making one real, deliberate live-fire\nrun and inspecting the actual output, not by reading the vendor's\ndocumentation or by only checking a dry-run's structured payload. The\ngeneral lesson: a dry run that only validates \"the payload we built has the\nright shape\" cannot catch bugs that live in the vendor's actual handling of\nthat payload, or in the rendered content itself (a missing placeholder\nsubstitution won't show up in a variables list) \u2014 at least one real,\ncareful live execution earns its cost before trusting an automated pipeline\nthat talks to an external service."}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h2,{id:"left-out",children:"Left out"}),"\n",(0,i.jsxs)(n.p,{children:["The following exist in the source material this page was drawn from but\nare not included above because a generalized description would still\namount to a specific, identifiable account of what was investigated, for\nwhom, and what was found \u2014 left out rather than thinly disguised, per the\n",(0,i.jsx)(n.a,{href:"./classification",children:"classification policy"}),":"]}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"The exact multi-service architecture connecting a specific mail/directory\nplatform's read-only audit scan to a specific rendering-and-delivery\npipeline, insofar as describing it accurately requires naming the checks\nbeing run and the categories of finding they produce for one particular\naccount."}),"\n",(0,i.jsx)(n.li,{children:'A third party\'s own internal working files for a specific business\narrangement (extraction prompts, a Python extraction script, task\ninstructions) \u2014 not Panderose tooling, and out of scope for "internal\nengineering practice" regardless of classification. One operationally\nurgent fact from that material (a live, unrotated credential) has been\nflagged separately, outside this docs site, rather than written up here\nas technique.'}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}}}]);